body.script:
const STORAGE_KEY = 'chanlite_catalog_dark_v1';

function generateId(prefix) {
  return `${prefix}-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`;
}

function createDefaultState() {
  const boards = [
    {
      id: 'g',
      name: '/g/',
      description: 'Technology',
      threads: [
        {
          id: 'g-thread-1',
          subject: 'Why build a 4chan clone in one file?',
          createdAt: new Date().toISOString(),
          posts: [
            {
              id: 'g-post-1',
              no: 1,
              author: 'Anonymous',
              subject: 'Why build a 4chan clone in one file?',
              text: 'Because it is fun and useful for prototypes. You can fake the whole UI in a browser without a backend.',
              image: '',
              createdAt: new Date().toISOString()
            },
            {
              id: 'g-post-2',
              no: 2,
              author: 'Anonymous',
              subject: '',
              text: 'It works for demos, prototypes, or mockups. Real email/auth still needs a server.',
              image: '',
              createdAt: new Date().toISOString()
            },
            {
              id: 'g-post-3',
              no: 3,
              author: 'Anonymous',
              subject: '',
              text: '>>1\nThis is how quote replies work in the UI.',
              image: '',
              createdAt: new Date().toISOString()
            }
          ]
        }
      ]
    },
    {
      id: 'b',
      name: '/b/',
      description: 'Random',
      threads: []
    },
    {
      id: 'pol',
      name: '/pol/',
      description: 'Politics',
      threads: []
    },
    {
      id: 'a',
      name: '/a/',
      description: 'Anime',
      threads: []
    }
  ];

  return {
    activeBoardId: 'g',
    activeThreadId: null,
    darkMode: false,
    boards
  };
}

function loadState() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return createDefaultState();

    const parsed = JSON.parse(raw);
    if (!parsed || !Array.isArray(parsed.boards)) return createDefaultState();

    parsed.boards = parsed.boards.map(board => ({
      id: board.id || generateId('board'),
      name: board.name || `/${String(board.id || 'board').replace(/[^a-z0-9]/gi, '').toLowerCase()}/`,
      description: board.description || 'Custom board',
      threads: Array.isArray(board.threads) ? board.threads : []
    }));

    if (!parsed.activeBoardId || !parsed.boards.some(b => b.id === parsed.activeBoardId)) {
      parsed.activeBoardId = parsed.boards[0].id;
    }

    return parsed;
  } catch {
    return createDefaultState();
  }
}

let state = loadState();

function saveState() {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(state));
}

function getBoard(boardId) {
  return state.boards.find(board => board.id === boardId) || state.boards[0];
}

function getThread(boardId, threadId) {
  const board = getBoard(boardId);
  return board.threads.find(thread => thread.id === threadId);
}

function escapeHtml(str='') {
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function formatTime(iso) {
  if (!iso) return 'just now';
  const diff = Date.now() - new Date(iso).getTime();
  const sec = Math.max(1, Math.floor(diff / 1000));
  if (sec < 60) return `${sec}s ago`;
  const min = Math.floor(sec / 60);
  if (min < 60) return `${min}m ago`;
  const hours = Math.floor(min / 60);
  if (hours < 24) return `${hours}h ago`;
  const days = Math.floor(hours / 24);
  return `${days}d ago`;
}

function renderBoardList() {
  const boardList = document.getElementById('boardList');
  boardList.innerHTML = '';

  state.boards.forEach(board => {
    const btn = document.createElement('button');
    btn.type = 'button';
    btn.className = 'board-btn' + (state.activeBoardId === board.id ? ' active' : '');
    btn.innerHTML = `
      <span class="board-name">${escapeHtml(board.name)}</span>
      <span class="board-desc">${escapeHtml(board.description)}</span>
    `;
    btn.addEventListener('click', () => {
      state.activeBoardId = board.id;
      state.activeThreadId = null;
      render();
    });
    boardList.appendChild(btn);
  });
}

function renderRichText(text = '') {
  const escaped = escapeHtml(text).replace(/\\n/g, '<br>');
  return escaped.replace(/(>>\\d+)/g, '<span class=\"quote\" data-quote=\"$1\">$1</span>');
}

function fileToDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ''));
    reader.onerror = () => reject(new Error('Failed to read file'));
    reader.readAsDataURL(file);
  });
}

function renderBoardView() {
  const board = getBoard(state.activeBoardId);
  const totalPosts = board.threads.reduce((sum, t) => sum + t.posts.length, 0);

  document.getElementById('mainContent').innerHTML = `
    <div class="board-header">
      <h2>
        <span class="tag">${escapeHtml(board.name)}</span>
        <span>${escapeHtml(board.description)}</span>
      </h2>
      <div class="board-info">${board.threads.length} threads • ${totalPosts} posts</div>
    </div>

    <div class="toolbar">
      <span class="pill">Anonymous</span>
      <span class="pill">${board.threads.length} threads</span>
      <span class="pill">${totalPosts} posts</span>
    </div>

    <form id="newThreadForm" class="compose">
      <h3>Start a new thread</h3>
      <div class="grid">
        <div class="field">
          <label for="threadSubject">Subject</label>
          <input id="threadSubject" type="text" placeholder="Thread subject" />
        </div>
        <div class="field">
          <label for="threadAuthor">Name</label>
          <input id="threadAuthor" type="text" value="Anonymous" />
        </div>
        <div class="field full">
          <label for="threadText">Comment</label>
          <textarea id="threadText" placeholder="Write something..." required></textarea>
        </div>
        <div class="field full">
          <label for="threadImage">Image (optional)</label>
          <input id="threadImage" type="file" accept="image/*" />
        </div>
      </div>

      <div style="display:flex; justify-content:flex-end; margin-top: 10px;">
        <button type="submit">Create Thread</button>
      </div>
    </form>

    <div class="catalog">
      ${board.threads.length === 0 ? `
        <div class="thread-card">
          <div class="subject">No threads yet</div>
          <div class="preview">This board is empty. Start the first thread.</div>
        </div>
      ` : board.threads.map(thread => {
        const op = thread.posts[0];
        const preview = (op && op.text ? op.text : '').slice(0, 220);
        const replies = Math.max(0, thread.posts.length - 1);

        return `
          <div class="thread-card">
            <div class="meta">
              <span>${escapeHtml(op ? op.author : 'Anonymous')}</span>
              <span>•</span>
              <span>${formatTime(op ? op.createdAt : new Date().toISOString())}</span>
            </div>

            <div class="subject">${escapeHtml(thread.subject || 'No subject')}</div>
            <div class="preview">${escapeHtml(preview || 'No text')}</div>
            <div class="stats">${thread.posts.length} posts • ${replies} replies</div>

            <button type="button" class="secondary open" data-thread-open="${thread.id}">Open Thread</button>
          </div>
        `;
      }).join('')}
    </div>
  `;

  document.getElementById('newThreadForm').addEventListener('submit', async (event) => {
    event.preventDefault();

    const subject = document.getElementById('threadSubject').value.trim() || 'No subject';
    const author = document.getElementById('threadAuthor').value.trim() || 'Anonymous';
    const text = document.getElementById('threadText').value.trim();
    const fileInput = document.getElementById('threadImage');
    const image = fileInput && fileInput.files && fileInput.files[0] ? await fileToDataUrl(fileInput.files[0]) : '';

    if (!text) return;

    const board = getBoard(state.activeBoardId);
    board.threads.unshift({
      id: generateId('thread'),
      subject,
      createdAt: new Date().toISOString(),
      posts: [{
        id: generateId('post'),
        no: 1,
        author,
        subject,
        text,
        image,
        createdAt: new Date().toISOString()
      }]
    });

    saveState();
    render();
  });

  document.querySelectorAll('[data-thread-open]').forEach(button => {
    button.addEventListener('click', () => {
      state.activeThreadId = button.getAttribute('data-thread-open');
      render();
    });
  });
}

function renderThreadView() {
  const thread = getThread(state.activeBoardId, state.activeThreadId);

  if (!thread) {
    state.activeThreadId = null;
    render();
    return;
  }

  const postsHtml = thread.posts.map(post => `
    <div class="post ${post.no === 1 ? 'op' : ''}">
      <div class="post-no">#${post.no}</div>
      <div class="post-body">
        <div class="post-head">
          <span class="post-subject">${escapeHtml(post.subject || '')}</span>
          <span class="post-author">${escapeHtml(post.author || 'Anonymous')}</span>
          <span>${formatTime(post.createdAt)}</span>
        </div>

        ${post.image ? `<img class="post-image" src="${post.image}" alt="uploaded image" />` : ''}

        <div class="post-text">${renderRichText(post.text || '')}</div>
      </div>
    </div>
  `).join('');

  document.getElementById('mainContent').innerHTML = `
    <div class="thread-view">
      <button type="button" class="secondary back-btn" id="backBtn">← Back to board</button>

      <div class="posts">
        ${postsHtml}
      </div>

      <div class="reply-box">
        <h3>Reply to thread</h3>
        <form id="replyForm">
          <div class="grid">
            <div class="field">
              <label for="replyName">Name</label>
              <input id="replyName" type="text" value="Anonymous" />
            </div>

            <div class="field">
              <label for="replyImage">Image (optional)</label>
              <input id="replyImage" type="file" accept="image/*" />
            </div>

            <div class="field full">
              <label for="replyText">Comment</label>
              <textarea id="replyText" placeholder="Write a reply..." required></textarea>
            </div>
          </div>

          <div style="display:flex; justify-content:flex-end; margin-top:10px;">
            <button type="submit">Post Reply</button>
          </div>
        </form>
      </div>
    </div>
  `;

  document.getElementById('backBtn').addEventListener('click', () => {
    state.activeThreadId = null;
    render();
  });

  document.getElementById('replyForm').addEventListener('submit', async (event) => {
    event.preventDefault();

    const text = document.getElementById('replyText').value.trim();
    if (!text) return;

    const author = document.getElementById('replyName').value.trim() || 'Anonymous';
    const fileInput = document.getElementById('replyImage');
    const image = fileInput && fileInput.files && fileInput.files[0] ? await fileToDataUrl(fileInput.files[0]) : '';

    const thread = getThread(state.activeBoardId, state.activeThreadId);
    thread.posts.push({
      id: generateId('post'),
      no: thread.posts.length + 1,
      author,
      subject: '',
      text,
      image,
      createdAt: new Date().toISOString()
    });

    saveState();
    render();
  });

  document.querySelectorAll('.quote').forEach(node => {
    node.addEventListener('click', () => {
      const quote = node.getAttribute('data-quote');
      const textarea = document.getElementById('replyText');
      textarea.value = textarea.value.trim() ? `${textarea.value.trim()}\\n${quote}\\n` : `${quote}\\n`;
      textarea.focus();
    });
  });
}

function render() {
  renderBoardList();

  if (state.activeThreadId) {
    renderThreadView();
  } else {
    renderBoardView();
  }

  document.body.classList.toggle('dark', !!state.darkMode);
  const button = document.getElementById('themeToggle');
  button.textContent = state.darkMode ? 'Light mode' : 'Dark mode';
  saveState();
}

document.getElementById('themeToggle').addEventListener('click', () => {
  state.darkMode = !state.darkMode;
  render();
});

document.getElementById('newBoardBtn').addEventListener('click', () => {
  const input = document.getElementById('newBoardInput');
  const raw = (input.value || '').trim().toLowerCase().replace(/[^a-z0-9]/g, '');
  const id = raw.slice(0, 12);

  if (!id) return;

  const exists = state.boards.some(board => board.id === id);
  if (exists) {
    state.activeBoardId = id;
    state.activeThreadId = null;
    input.value = '';
    render();
    return;
  }

  state.boards.push({
    id,
    name: `/${id}/`,
    description: 'Custom board',
    threads: []
  });

  state.activeBoardId = id;
  state.activeThreadId = null;
  input.value = '';
  saveState();
  render();
});

render();
